/* @autogenerated */
package net.civeira.phylax.features.document.rendering.application.usecase.render;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.access.tenant.domain.TenantRef;
import net.civeira.phylax.features.document.rendering.domain.RenderedAsset;
import net.civeira.phylax.features.document.rendering.domain.RenderedTemplate;
import net.civeira.phylax.features.document.rendering.domain.TemplateRenderRequest;
import net.civeira.phylax.features.document.rendering.domain.gateway.TemplateRenderGateway;
import net.civeira.phylax.features.document.template.domain.Template;
import net.civeira.phylax.features.document.template.domain.TemplateChannelOptions;
import net.civeira.phylax.features.document.template.domain.gateway.TemplateFilter;
import net.civeira.phylax.features.document.template.domain.gateway.TemplateReadRepositoryGateway;
import net.civeira.phylax.features.document.templatesnippet.domain.gateway.TemplateSnippetFilter;
import net.civeira.phylax.features.document.templatesnippet.domain.gateway.TemplateSnippetReadRepositoryGateway;
import net.civeira.phylax.features.document.templatevariable.domain.gateway.TemplateVariableFilter;
import net.civeira.phylax.features.document.templatevariable.domain.gateway.TemplateVariableReadRepositoryGateway;
import net.civeira.phylax.features.document.templateversion.domain.TemplateVersion;
import net.civeira.phylax.features.document.templateversion.domain.gateway.TemplateVersionFilter;
import net.civeira.phylax.features.document.templateversion.domain.gateway.TemplateVersionReadRepositoryGateway;
import net.civeira.phylax.features.document.theme.domain.ThemeRef;
import net.civeira.phylax.features.document.theme.domain.gateway.ThemeReadRepositoryGateway;

/**
 * Orchestrates the resolution and rendering of a stored template into a document.
 *
 * <p>
 * Responsibilities of this use case:
 * <ol>
 * <li>Resolve the best-matching {@link Template} (tenant-specific first, then global).</li>
 * <li>Select the latest {@link TemplateVersion} for that template.</li>
 * <li>Merge tenant-level {@code TemplateVariable} defaults with call-site overrides.</li>
 * <li>Load tenant {@code TemplateSnippet} records for partial resolution.</li>
 * <li>Delegate the actual string substitution to the {@link TemplateRenderGateway}.</li>
 * </ol>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class TemplateRenderUsecase {

  private final TemplateReadRepositoryGateway templateGateway;
  private final TemplateVersionReadRepositoryGateway versionGateway;
  private final TemplateVariableReadRepositoryGateway variableGateway;
  private final TemplateSnippetReadRepositoryGateway snippetGateway;
  private final TemplateRenderGateway renderGateway;
  private final ThemeReadRepositoryGateway themeGateway;

  /**
   * Render the template identified by {@code input.code} and {@code input.channel}.
   *
   * @param input Render parameters (code, channel, tenant, locale, call-site variables).
   * @return The rendered document, or {@link Optional#empty()} if no matching template or version
   *         exists.
   */
  public Optional<RenderedTemplate> render(final TemplateRenderInput input) {
    Optional<Template> template =
        resolveTemplate(input.getCode(), input.getChannel(), input.getTenant().orElse(null));
    if (template.isEmpty()) {
      log.debug("No enabled template found: code='{}' channel='{}' tenant='{}'", input.getCode(),
          input.getChannel(), input.getTenant().map(TenantRef::getUid).orElse("global"));
      return Optional.empty();
    }

    Optional<TemplateVersion> version = latestVersion(template.get());
    if (version.isEmpty()) {
      log.debug("Template '{}' has no versions", template.get().getUid());
      return Optional.empty();
    }

    TemplateVersion tv = version.get();
    Map<String, String> variables =
        mergeVariables(input.getTenant().orElse(null), input.getVariables());
    Map<String, String> snippets = loadSnippets(input.getTenant().orElse(null));
    List<RenderedAsset> assets = loadThemeAssets(template.get());

    RenderedTemplate rendered = renderGateway.render(TemplateRenderRequest.builder()
        .subject(tv.getSubject().orElse(null)).htmlContent(tv.getContentHtml())
        .textContent(tv.getContentText().orElse(null)).snippets(snippets).variables(variables)
        .outputFormat(input.getOutputFormat()).assets(assets).build());

    return Optional.of(rendered);
  }

  // ---------------------------------------------------------------------------
  // Private — domain coordination logic
  // ---------------------------------------------------------------------------

  /**
   * Resolves the best-matching template: tenant-specific (code + channel + tenant) first, then
   * global (code + channel, no tenant).
   */
  private Optional<Template> resolveTemplate(final String code,
      final TemplateChannelOptions channel, final TenantRef tenant) {

    List<Template> candidates = templateGateway.list(TemplateFilter.builder().code(code).build());

    if (tenant != null) {
      Optional<Template> specific =
          candidates.stream().filter(t -> channel == t.getChannel()).filter(t -> t.isEnabled())
              .filter(t -> t.getTenant().flatMap(tr -> Optional.ofNullable(tr.getUid()))
                  .map(uid -> uid.equals(tenant.getUid())).orElse(false))
              .findFirst();
      if (specific.isPresent()) {
        return specific;
      }
    }

    return candidates.stream().filter(t -> channel == t.getChannel()).filter(t -> t.isEnabled())
        .filter(t -> t.getTenant().isEmpty()).findFirst();
  }

  /** Returns the version with the highest version counter (most recent). */
  private Optional<TemplateVersion> latestVersion(final Template template) {
    return versionGateway.list(TemplateVersionFilter.builder().template(template).build()).stream()
        .max(Comparator.comparingLong(tv -> tv.getVersion().orElse(0)));
  }

  /**
   * Builds the flat variable map: tenant defaults first, then call-site overrides on top.
   */
  private Map<String, String> mergeVariables(final TenantRef tenant,
      final Map<String, String> overrides) {
    Map<String, String> vars = new HashMap<>();
    if (tenant != null) {
      variableGateway.list(TemplateVariableFilter.builder().tenant(tenant).build()).stream()
          .filter(v -> v.isEnabled())
          .forEach(v -> v.getValue().ifPresent(val -> vars.put(v.getCode(), val)));
    }
    vars.putAll(overrides);
    return vars;
  }

  /**
   * Loads CSS assets from the theme associated with the template, if any. Returns an empty list
   * when the template has no theme or the theme has no custom CSS.
   */
  private List<RenderedAsset> loadThemeAssets(final Template template) {
    Optional<ThemeRef> themeRef = template.getTheme();
    if (themeRef.isEmpty()) {
      return List.of();
    }
    List<RenderedAsset> assets = new ArrayList<>();
    themeGateway.resolve(themeRef.get()).getCustomCss().ifPresent(css -> assets.add(RenderedAsset
        .builder().code("theme-css").contentType("text/css").content(css).embedded(false).build()));
    return assets;
  }

  /** Loads all enabled snippets for the tenant, indexed by code. */
  private Map<String, String> loadSnippets(final TenantRef tenant) {
    if (tenant == null) {
      return Map.of();
    }
    Map<String, String> snippets = new HashMap<>();
    snippetGateway.list(TemplateSnippetFilter.builder().tenant(tenant).build()).stream()
        .filter(s -> s.isEnabled()).forEach(s -> snippets.put(s.getCode(), s.getContentHtml()));
    return snippets;
  }
}
